pragma solidity >=0.8.0;
contract StoragePackingProbe {
    uint8 public a;
    bool public b;
    int32 public c;
    uint8 public d;
    uint256 public wide;
    string public text;
    bytes public blob;

    function setSmall(uint8 _a, bool _b, int32 _c, uint8 _d) public {
        a = _a; b = _b; c = _c; d = _d;
    }
    function setWide(uint256 w) public { wide = w; }
    function setText(string memory t) public { text = t; }
    function setBlob(bytes memory bl) public { blob = bl; }
    function clearA() public { delete a; }
    function length() public view returns (uint256) { return bytes(text).length + blob.length; }
}
